            .replace(/\\s+/g, \'-\')
            .replace(/-+/g, \'-\')
            .replace(/^-+|-+$/g, \'\');
        slugInput.value = pinyin;
    }
});

// 验证别名格式
document.getElementById(\'slug\')?.addEventListener(\'blur\', function(e) {
    const value = e.target.value;
    if (value && !/^[a-z0-9-]+$/.test(value)) {
        alert(\'别名只能包含小写字母、数字和横杠\');
        e.target.value = value.replace(/[^a-z0-9-]/g, \'\');
    }
});

// 表单提交处理
document.getElementById(\'categoryForm\')?.addEventListener(\'submit\', function(e) {
    e.preventDefault();
    
    const form = this;
    const button = form.querySelector(\'button[type="submit"]\');
    const originalText = button.innerHTML;
    
    // 禁用提交按钮，防止重复提交
    button.disabled = true;
    button.innerHTML = \'<i class="bi bi-arrow-clockwise spinner"></i> 保存中...\';
    
    // 使用Fetch API提交表单
    fetch(form.action, {
        method: \'POST\',
        body: new FormData(form),
        headers: {
            \'X-Requested-With\': \'XMLHttpRequest\'
        }
    })
    .then(response => response.json())
    .then(data => {
        if (data.code === 0) {
            // 保存成功，跳转到栏目列表
            window.location.href = data.url || \'/admin/category\';
        } else {
            // 保存失败，显示错误信息
            alert(data.message || \'保存失败\');
            // 恢复提交按钮
            button.disabled = false;
            button.innerHTML = originalText;
        }
    })
    .catch(error => {
        console.error(\'保存失败:\', error);
        alert(\'保存失败，请重试\');
        // 恢复提交按钮
        button.disabled = false;
        button.innerHTML = originalText;
